local this = Player;

this.uid = nil;
this.SelfId = nil;
this.EnemyId = nil;
this.IsInLastRoom = false;
this.LastRoomData = nil;
this.showCard5 = 0;

this.nick = "";
this.headIcon = "200004201";--新玩家默认头像
this.frameId = 1001;
local level = 1;
this.exp = 0;
local gold = 0;--金币
local diamond = 0;--元宝
