Player.MoneyChangeEvent = {};--数量变化时需要被通知的，注册此事件
Player.LevelChangeEvent = {};--数量变化时需要被通知的，注册此事件

function Player:ctor()

end

---单例，方便外界调用
function Player.Instance()
    if instance == nil then
        instance = Player.new();
    end
    return instance;
end

function Player.Init()

end

function Player.Reset()
    Player.MoneyChangeEvent = {};
    Player.LevelChangeEvent = {};
end

function Player.InitUserData(userData)
    this.uid = userData.uid;
    this.nick = userData.nick;
    this.SetLevel(userData.level);
    LobbyCtrl.showedUpgradeLevel = Player.GetLevel();

    if (userData.exp ~= nil) then
        this.exp = userData.exp;
    else
        Debug.LogError("@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@Player.InitUserData::exp is nil");
    end
    Player.SetGold(userData.gold);
    Player.SetDiamond(userData.diamond);
    this.payTotal = userData.payTotal;
    if (userData.headIcon ~= nil) then
        this.headIcon = userData.headIcon;
    end
    Player.frameId = userData.frameId;
    ChangeHeadUICtrl.GetInstance():RefreshHeadFrame();
end

function Player.GetLevelUpExp(level)
    return DataManager.GetDataEntity(GameLogic.playerLevelDataTableName, level).Exp;
end

function Player.GetGold()
    return gold;
end
function Player.SetGold(g)
    gold = tonumber(g);
    for i, v in pairs(Player.MoneyChangeEvent) do
        if (v ~= nil) then
            v();
        end
    end
end

function Player.GetDiamond()
    return diamond;
end
function Player.SetDiamond(d)
    diamond = tonumber(d);
    for i, v in pairs(Player.MoneyChangeEvent) do
        if (v ~= nil) then
            v();
        end
    end
end

function Player.GetLevel()
    return level;
end
function Player.SetLevel(lvl)
    level = tonumber(lvl);
    for i, v in pairs(Player.LevelChangeEvent) do
        if (v ~= nil) then
            v();
        end
    end
    GuideManager.CheckHelp();---检查升级解锁
end

function Player.CreateHeadIcon(itemType, id)
    local tempHeadIcon;
    if (itemType == ItemType.Hero) then
        tempHeadIcon = 2 * Constant.headIconModeParam + id;
    end

    return tempHeadIcon;
end

---
---临时函数，用来取玩家头像对应的卡牌ID
---由于后续玩家头像可能会有非英雄的情况出现，所以当做卡牌ID使用
---
function Player.GetPlayerIconHeroId()
    local tempHeroId;
    tempHeroId = this.headIcon % 10000;
    return tempHeroId;
end

function Player.GetHeadIconSpriteName(headIcon)
    local headIconType = math.floor(headIcon / Constant.headIconModeParam + 0.5);
    local headIconId = headIcon % Constant.headIconModeParam;
    if (headIconType == ItemType.Hero) then
        return "hero_head_" .. DataManager.GetDataEntity(GameLogic.heroDataTableName, headIconId).Image;
    end

    return "";
end

function Player.GetHeadFrameSpriteName(frameId)
    local frameData = DataManager.GetDataEntity(GameLogic.headFrameDataTableName, frameId);
    if (frameData ~= nil) then
        return frameData.Image;
    else
        return "";
    end
end